    const cap: Uint<64> = 1000;
    assert newBid <= cap;
    // if bid is exactly cap, return true and emit an event (but event omitted for brevity)
    if newBid == cap {
        return true;
    }
    // otherwise, some processing
    const diff = newBid - prevBid;
    assert diff > 0;
    return true;
    // after return, there's supposed to be a fallback but it's unreachable
    const unused = 0;
}
```

